<?php $old=flash('old')??[]; ?><header class="admin-page-head"><div><a href="/admin/<?= e($resource) ?>">← <?= e($config['label']) ?></a><h1><?= e($title) ?></h1></div></header><form class="admin-form" method="post" action="<?= $record?'/admin/'.e($resource).'/'.(int)$record['id']:'/admin/'.e($resource) ?>"><?= csrf_field() ?><section class="admin-panel form-fields"><?php foreach($config['fields'] as $name=>$field): $value=$old[$name]??$record[$name]??''; ?><label class="field <?= ($field['type']??'')==='textarea'?'field-full':'' ?>"><?php if(($field['type']??'text')==='checkbox'): ?><input type="hidden" name="<?= e($name) ?>" value="0"><span class="toggle"><input type="checkbox" name="<?= e($name) ?>" value="1" <?= $value?'checked':'' ?>><i></i><?= e($field['label']) ?></span><?php else: ?><span><?= e($field['label']) ?></span><?php if(($field['type']??'text')==='textarea'): ?><textarea name="<?= e($name) ?>" <?= !empty($field['required'])?'required':'' ?>><?= e($value) ?></textarea><?php else: ?><input type="<?= ($field['type']??'text')==='number'?'number':'text' ?>" name="<?= e($name) ?>" value="<?= e($value) ?>" <?= !empty($field['required'])?'required':'' ?> <?= ($field['type']??'')==='number'?'step="any"':'' ?>><?php endif; ?><?php endif; ?></label><?php endforeach; ?></section><footer class="admin-save-bar"><a class="button button-outline" href="/admin/<?= e($resource) ?>">Cancel</a><button class="button" type="submit">Save record</button></footer></form>
